const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',route:'M5 7a3 3 0 1 0 0-6 3 3 0 0 0 0 6zm14 16a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM5 7v6a4 4 0 0 0 4 4h6M9 4h7a4 4 0 0 1 0 8h-4',archive:'M3 4h18v4H3zM5 8v13h14V8M9 12h6',truck:'M2 5h12v12H2zM14 10h5l3 4v3h-8M7 19a2 2 0 1 0-4 0 2 2 0 0 0 4 0zm14 0a2 2 0 1 0-4 0 2 2 0 0 0 4 0z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM9 3l1-2h4l1 2 3 2 2 1v4l-2 2v3l1 2-3 3-3-1h-3l-2 1-3-3 1-2v-3l-2-2V6l2-1z',plus:'M12 5v14M5 12h14',search:'M10.5 18a7.5 7.5 0 1 0 0-15 7.5 7.5 0 0 0 0 15zM16 16l5 5',chevron:'M9 5l7 7-7 7',back:'M19 12H5m6-6-6 6 6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',check:'M5 12l4 4L19 6',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20zM12 6v6l4 2',pin:'M12 22s8-7 8-13a8 8 0 0 0-16 0c0 6 8 13 8 13zM12 6a3 3 0 1 0 0 6 3 3 0 0 0 0-6z',more:'M5 12h.01M12 12h.01M19 12h.01',close:'M6 6l12 12M6 18 18 6',info:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20zM12 11v6M12 7h.01',alert:'M12 3 1 21h22L12 3zM12 9v5M12 17h.01',copy:'M8 8h13v13H8zM16 8V3H3v13h5',play:'M7 3l15 9-15 9V3z',pause:'M6 4h4v16H6zM14 4h4v16h-4z',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 13h8M8 17h6',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13z',save:'M4 3h14l3 3v15H3V3zM7 3v7h10V3M7 21v-7h10v7',refresh:'M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-3l2 3M4 17l2 3a8 8 0 0 0 13-3',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6L12 2zM8 12l3 3 5-6'};
const ico=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.route}"/></svg>`;
const events={pass:'Проезд',arrival:'Прибытие',departure:'Отправление',loading:'Погрузка',unloading:'Разгрузка',rest:'Отдых',overnight:'Ночёвка'};
const sources={user:'Контрольная отметка',gps:'GPS-запись',telemetry:'Исходная телеметрия',document:'Документ',driver:'Сообщение водителя',reconstruction:'Реконструкция',checkpoint:'Контрольная отметка',calculation:'Расчёт'};
const state={page:'trips',config:{},trips:[],total:0,offset:0,search:'',status:'',client:'',from:'',to:'',sort:'updated',trip:null,tab:'points',versions:[],version:null,exports:[],dirty:false,saveStatus:'',saving:false,edit:0,request:0,saveTimer:null,job:null,playIndex:0,playing:false,displayZone:'local',profiles:[],settings:{},map:null,mapToken:0,selectedPoint:null,importData:null};
let playerTimer, filterTimer, jobTimer;
async function api(path,options={}){const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers},body:options.body===undefined?undefined:JSON.stringify(options.body)});let data;try{data=await res.json()}catch{data={error:`Ошибка сервиса (${res.status})`}}if(!res.ok){let error=new Error(typeof data.error==='object'?data.error.message:data.error||data.message||`Ошибка ${res.status}`);error.status=res.status;error.data=data;throw error}return data}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toasts').append(el);setTimeout(()=>el.remove(),error?10000:4500)}
function date(v,short=false){if(!v)return'—';const d=new Date(v);return Number.isNaN(+d)?String(v):new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',...(short?{}:{year:'numeric'}),hour:'2-digit',minute:'2-digit'}).format(d)}
function localDate(v){return v?String(v).replace('T',' ').slice(0,19):'—'}
function num(v,d=0){return Number.isFinite(Number(v))?Number(v).toLocaleString('ru-RU',{maximumFractionDigits:d}):'—'}
function duration(s){s=Number(s||0);return`${Math.floor(s/3600)} ч ${Math.round(s%3600/60)} мин`}
function summary(v=state.version){return v?.result?.summary||{}}
function distance(v=state.version){const x=summary(v);return x.distanceM??x.totalDistanceM??x.distance??0}
function moving(v=state.version){const x=summary(v);return x.movingSeconds??x.movingS??x.driveSeconds??x.drivingSeconds??0}
function stopped(v=state.version){const x=summary(v);return x.stopSeconds??x.stoppedSeconds??x.restSeconds??0}
function resultChecks(){return state.lastErrorChecks||state.version?.result?.checks||[]}
function isStale(v=state.version){return !!v&&Number(v.revision??v.sourceRevision)!==Number(state.trip?.revision)}
function tripStatus(t){if(t===state.trip&&!t.status&&state.versions.length){const v=state.versions[0];t={...t,status:v.revision===t.revision?v.status:'stale'}}if(t.archived)return['Архив',''];if(t.status==='error'||t.status==='conflict')return['Есть конфликт','error'];if(t.status==='running'||t.status==='queued')return['Выполняется','running'];if(t.stale||t.isStale||t.status==='stale')return['Устарел','warn'];if(['completed','ready','calculated'].includes(t.status)||t.latestVersionId)return['Рассчитан','ready'];return['Черновик','']}
function badge(label,cls=''){return`<span class="status ${cls}">${esc(label)}</span>`}
function today(){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long',year:'numeric',timeZone:'Europe/Moscow'}).format(new Date())}
function shell(body){const focusId=document.activeElement?.id;const selection=document.activeElement?.selectionStart;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#" class="brand" data-nav="trips"><span class="brand-symbol">р</span><div><div class="brand-name">рейс<span style="color:#a9dcbf">.</span></div><div class="brand-note">Маршруты и данные</div></div></a><div class="nav-label">Рабочее пространство</div><nav><button class="nav-btn ${['trips','card'].includes(state.page)?'active':''}" data-nav="trips">${ico('route')}<span>Все рейсы</span><span class="count">${state.total||0}</span></button><button class="nav-btn ${state.page==='profiles'?'active':''}" data-nav="profiles">${ico('truck')}<span>Профили фур</span></button><button class="nav-btn ${state.page==='archive'?'active':''}" data-nav="archive">${ico('archive')}<span>Архив</span></button></nav><div class="nav-label" style="margin-top:30px">Система</div><button class="nav-btn ${state.page==='settings'?'active':''}" data-nav="settings">${ico('settings')}<span>Настройки</span></button><div class="sidebar-bottom"><div style="font-size:10px;color:#bdd1c8"><span class="private-dot"></span>Личное пространство</div><p class="sidebar-note">Ваши рейсы и версии<br>сохраняются в базе приложения</p><div class="user"><span class="avatar">В</span><div>Владимир<div style="font-size:9px;color:#78949a;margin-top:4px">Владелец пространства</div></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Рабочее пространство <span>/</span><strong>${esc(({trips:'Реестр рейсов',archive:'Архив рейсов',profiles:'Профили фур',settings:'Настройки',card:state.trip?.title||'Рейс'})[state.page])}</strong></div><div class="top-right"><span class="session-state"><span class="private-dot"></span>Постоянное хранение</span><span>${today()}</span></div></header><div class="content">${body}</div></main></div>`;bindInputs();if(['search','client-filter'].includes(focusId)){const focused=document.getElementById(focusId);focused?.focus();try{focused?.setSelectionRange(selection,selection)}catch{}}if(state.page==='card'&&state.tab==='points')initMap()}
function registry(){const archived=state.page==='archive';const ready=state.trips.filter(t=>tripStatus(t)[1]==='ready').length;const drafts=state.trips.filter(t=>tripStatus(t)[0]==='Черновик').length;const pending=state.trips.filter(t=>['warn','error'].includes(tripStatus(t)[1])).length;shell(`<div class="page-heading"><div><div class="eyebrow">Ваши маршруты, под контролем</div><h1>${archived?'Архив рейсов':'Реестр рейсов'}</h1><p class="subtitle">${archived?'Сохранённые рейсы, к которым можно вернуться.':'Сохраняйте опорные точки, восстанавливайте маршрут и продолжайте работу в любое время.'}</p></div><div class="heading-actions"><button data-action="demo">${ico('play')}Открыть пример</button><button class="primary" data-action="new">${ico('plus')}Новый рейс</button></div></div><div class="stats"><div class="stat"><div class="stat-label">${ico('route')}Всего рейсов</div><div class="stat-value">${num(state.total)}</div><div class="stat-foot">В постоянном реестре</div></div><div class="stat accent"><div class="stat-label">${ico('check')}Готовы к выгрузке</div><div class="stat-value">${ready}</div><div class="stat-foot">Рассчитаны на этой странице</div></div><div class="stat"><div class="stat-label">${ico('file')}В работе</div><div class="stat-value">${drafts}</div><div class="stat-foot">Черновики на этой странице</div></div><div class="stat"><div class="stat-label">${ico('clock')}Требуют внимания</div><div class="stat-value">${pending}</div><div class="stat-foot">Конфликты и устаревшие версии</div></div></div><section class="panel"><div class="panel-title"><div><h2>${archived?'Сохранённый архив':'Все рейсы'} <span class="pill" style="margin-left:7px">${state.total}</span></h2></div><button class="ghost small" data-action="refresh">${ico('refresh')}Обновить</button></div><div class="filters"><div class="search">${ico('search')}<input id="search" aria-label="Поиск рейсов" placeholder="Номер рейса, клиент или машина" value="${esc(state.search)}"></div><select id="status-filter" aria-label="Состояние расчёта"><option value="">Все состояния</option>${[['draft','Черновик'],['completed','Рассчитан'],['conflict','Конфликт'],['stale','Устаревший']].map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><input id="client-filter" aria-label="Фильтр по клиенту" placeholder="Клиент" value="${esc(state.client)}" style="width:125px"><span class="filters-label">Период</span><input type="date" id="from-filter" aria-label="Начало периода" value="${esc(state.from)}"><input type="date" id="to-filter" aria-label="Конец периода" value="${esc(state.to)}"><select id="sort-filter" aria-label="Сортировка"><option value="updated" ${state.sort==='updated'?'selected':''}>Сначала новые</option><option value="title" ${state.sort==='title'?'selected':''}>По названию</option><option value="period" ${state.sort==='period'?'selected':''}>По дате рейса</option></select></div>${state.trips.length?`<div class="table-scroll"><table><thead><tr><th>Рейс / маршрут</th><th>Клиент</th><th>Машина</th><th>Период</th><th>Опоры</th><th>Состояние</th><th>Изменён</th><th></th></tr></thead><tbody>${state.trips.map(t=>{const st=tripStatus(t),p=t.points||[];return`<tr class="trip-row" data-open="${esc(t.id)}"><td><div class="trip-title"><span class="trip-icon">${ico('route')}</span><div><div class="trip-name">${esc(t.title||'Без названия')}</div><div class="trip-id">${esc(t.number||t.id?.slice(0,8))}${t.demo?' · Демо':''}</div></div></div></td><td>${esc(t.client||'—')}</td><td>${esc(t.vehicle||'—')}</td><td><div>${localDate(t.startTime||t.start||p[0]?.localTime).slice(0,16)}</div><div class="secondary" style="margin-top:4px">${localDate(t.endTime||t.end||p.at(-1)?.localTime).slice(0,16)}</div></td><td>${t.pointCount??p.length??0}</td><td>${badge(...st)}</td><td class="secondary">${date(t.updatedAt,true)}</td><td><button class="ghost icon-button" data-menu="${esc(t.id)}" aria-label="Действия с рейсом">${ico('more')}</button></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-symbol">${ico('route')}</div><h2>${state.search||state.status||state.client?'Рейсы не найдены':archived?'Здесь будет архив':'Первый маршрут начинается с рейса'}</h2><p>${state.search||state.status||state.client?'Попробуйте изменить фильтры поиска.':archived?'Архивируйте завершённые рейсы. Все опоры, версии и выгрузки останутся доступны.':'Добавьте известные координаты и время. Система построит расчётный вариант движения и предложит отдых.'}</p><div class="empty-actions"><button class="primary" data-action="new">${ico('plus')}Создать рейс</button><button data-action="demo">Посмотреть на примере</button></div></div>`}<div class="table-footer"><span>${state.total?`${state.offset+1}–${Math.min(state.offset+state.trips.length,state.total)} из ${state.total} рейсов`:'Нет сохранённых рейсов'}</span><div style="display:flex;gap:7px"><button class="small" data-action="previous" ${state.offset===0?'disabled':''}>Назад</button><button class="small" data-action="next" ${state.offset+state.trips.length>=state.total?'disabled':''}>Далее</button></div></div></section><div class="hint-card">${ico('info')}<p><strong>Известные факты и расчёт — отдельно.</strong><br>Восстановленный трек — объяснимый вариант по контрольным точкам. Предполагаемые остановки сохраняют расчётное происхождение.</p><button class="text-button link-btn" data-nav="settings">Об интеграции →</button></div><div class="bottom-note">${ico('shield')}Данные хранятся в базе приложения. Резервную копию рейсов и результатов можно создать в настройках.</div>`)}
async function loadTrips(){const request=++state.request;const p=new URLSearchParams({search:state.search,archive:state.page==='archive'?'1':'0',status:state.status,client:state.client,from:state.from,to:state.to,sort:state.sort,offset:state.offset,limit:30});try{const r=await api('/api/trips?'+p);if(request!==state.request)return;state.trips=r.items||[];state.total=r.total||0;registry()}catch(e){toast(e.message,true);registry()}}
function newTripDialog(){modal('Новый рейс',`<p class="modal-note">Сначала укажите название и режим времени. Клиента и машину можно добавить позже.</p><form id="new-trip-form" class="form-grid two"><div class="field wide"><label for="new-title">Номер или название рейса</label><input id="new-title" name="title" required autofocus placeholder="Например, РС-1042 · Москва — Казань"></div><div class="field"><label for="new-client">Клиент</label><input id="new-client" name="client" placeholder="Необязательно"></div><div class="field"><label for="new-vehicle">Машина</label><input id="new-vehicle" name="vehicle" placeholder="Госномер или название"></div><div class="field"><label for="new-time">Как введено время отметок</label><select id="new-time" name="timeMode"><option value="single">Единый часовой пояс</option><option value="local">Местное время каждой точки</option></select></div><div class="field"><label for="new-zone">Единый / исходный пояс IANA</label><input id="new-zone" name="timezone" value="Europe/Moscow" required></div></form>`,`<button data-close>Отмена</button><button class="primary" data-action="create-trip">${ico('plus')}Создать рейс</button>`)}
function modal(title,body,foot=''){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="ghost icon-button" data-close aria-label="Закрыть">${ico('close')}</button></div><div class="modal-body">${body}</div>${foot?`<div class="modal-foot">${foot}</div>`:''}`;if(!el.open)el.showModal()}
async function openTrip(id){if(!await flushSave())return;stopPlayback();const req=++state.request;try{const [trip,versions,exports]=await Promise.all([api('/api/trips/'+encodeURIComponent(id)),api('/api/trips/'+encodeURIComponent(id)+'/versions'),api('/api/trips/'+encodeURIComponent(id)+'/exports')]);if(req!==state.request)return;state.trip=trip;state.lastErrorChecks=null;state.page='card';state.tab='points';state.versions=versions.items||[];state.exports=exports.items||[];state.version=null;state.dirty=false;state.saveStatus='Сохранено';state.job=null;state.playIndex=0;state.selectedPoint=null;if(state.versions.length){const latest=state.versions.find(v=>v.status==='completed'||v.result)||state.versions[0];state.version=await api('/api/versions/'+latest.id);if(req!==state.request)return}history.replaceState(null,'','#trip='+encodeURIComponent(id));card();}catch(e){toast(e.message,true)}}
function card(){if(!state.trip)return;const t=state.trip;shell(`<button class="back ghost" data-nav="trips">${ico('back')}К реестру рейсов</button><div class="page-heading card-heading"><div style="flex:1;min-width:0"><div class="eyebrow">${esc(t.number||'Карточка рейса')} <span style="color:#97a79d;margin-left:8px">${esc(t.id?.slice(0,8))}</span></div><h1><input data-trip="title" aria-label="Название рейса" value="${esc(t.title)}" placeholder="Название рейса"></h1><div class="trip-meta"><span>${ico('truck')}</span><input data-trip="vehicle" aria-label="Машина" placeholder="Добавить машину" value="${esc(t.vehicle)}"><span class="meta-sep"></span><input data-trip="client" aria-label="Клиент" placeholder="Добавить клиента" value="${esc(t.client)}"><span class="meta-sep"></span>${badge(...tripStatus(t))}${t.demo?'<span class="pill">Демонстрационные данные</span>':''}</div></div><div style="display:flex;align-items:flex-end;flex-direction:column;gap:8px"><div id="save-state" class="save-state">${saveLabel()}</div><div class="heading-actions"><button data-action="save">${ico('save')}Сохранить</button><button data-action="export" ${!state.version?.result?.track?.length?'disabled':''}>${ico('download')}Экспорт Excel</button></div></div></div>${t.demo?'<div class="alert">'+ico('info')+'Демонстрационный рейс: геометрия создана для проверки работы приложения и не подтверждает реальный дорожный путь.</div>':''}<div id="stale-notice">${staleNotice()}</div><div class="toolbar"><button data-action="route">${ico('route')}Построить маршрут</button><button class="primary" data-action="calculate" ${state.job?'disabled':''}>${state.job?'<span class="spinner"></span>':' '+ico('play')}${state.job?'Рассчитывается…':'Рассчитать'}</button><button data-action="variant" ${!state.version?'disabled':''}>${ico('copy')}Создать вариант</button><span class="spacer"></span><span class="mini-label" style="align-self:center">Редакция ${t.revision??1} · ${t.timeMode==='local'?'Местное время точек':esc(t.timezone||'Europe/Moscow')}</span></div><nav class="tabs" aria-label="Разделы рейса">${[['points','Маршрут и точки',t.points?.length],['parameters','Параметры'],['stops','Остановки',state.version?.result?.stops?.length],['checks','Проверки',resultChecks().length],['versions','Версии',state.versions.length],['exports','Выгрузки',state.exports.length]].map(([id,label,count])=>`<button class="tab ${state.tab===id?'active':''}" data-tab="${id}">${label}${count?`<span class="tab-count">${count}</span>`:''}</button>`).join('')}</nav><div id="tab-content">${tabContent()}</div><div class="bottom-note">${ico('info')}Расчётное восстановление маршрута. Неизвестные условия дороги и места отдыха не считаются подтверждёнными фактами.</div>`)}
function saveLabel(){return`${state.saving?'<span class="spinner"></span>':ico(state.saveStatus?.startsWith('Ошибка')?'alert':'check')}<span>${esc(state.saving?'Сохраняется…':state.saveStatus||'Сохранено')}</span>`}
function staleNotice(){return isStale()?`<div class="alert">${ico('clock')}Вы просматриваете историческую версию: исходные данные изменились. Для актуального результата нажмите «Рассчитать».</div>`:''}
function tabContent(){return({points:pointsTab,parameters:parametersTab,stops:stopsTab,checks:checksTab,versions:versionsTab,exports:exportsTab})[state.tab]()}
function pointsTab(){const t=state.trip,p=t.points||[],track=state.version?.result?.track||[];return`<div class="work-grid"><section><div class="map-panel"><div class="map-canvas" id="map"></div><div class="map-top"><div class="map-badge ${t.demo?'demo':''}">${ico(t.demo?'info':'pin')}${t.demo?'Демонстрационная схема':state.config.mapKey?'Яндекс Карты':'Схема · подложка карты не подключена'}</div><button class="small" data-action="map-add">${ico('plus')}Точка на карте</button></div><div id="map-point-detail"></div><div class="map-bottom"><div class="map-legend"><span><i class="legend-dot"></i>Опорная точка</span><span><i class="legend-dot calculated"></i>Расчётный путь</span><span><i class="legend-dot stop"></i>Предполагаемый отдых</span></div><span class="map-copyright">WGS84 · ${state.config.mapKey?'Яндекс':'схематическое отображение'}</span></div>${!state.config.mapKey?'<div class="map-message">Для географической подложки подключите браузерный ключ Яндекс Карт в окружении приложения.</div>':''}</div><div class="playback"><button class="icon-button small" data-action="play" aria-label="Воспроизведение" ${!track.length?'disabled':''}>${ico(state.playing?'pause':'play')}</button><span id="play-time">${track.length?displayTime(track[state.playIndex]||track[0]):'Нет расчётного трека'}</span><input id="timeline" aria-label="Временная шкала рейса" type="range" min="0" max="${Math.max(0,track.length-1)}" value="${state.playIndex}" ${!track.length?'disabled':''}><select class="display-zone" id="display-zone" aria-label="Пояс отображения"><option value="local" ${state.displayZone==='local'?'selected':''}>Местное время</option><option value="Europe/Moscow" ${state.displayZone==='Europe/Moscow'?'selected':''}>Московское время</option><option value="UTC" ${state.displayZone==='UTC'?'selected':''}>UTC</option></select><div class="playback-stats"><span id="play-speed"><strong>0</strong> км/ч</span><span id="play-distance"><strong>0</strong> км</span></div></div></section><aside class="route-summary"><div class="summary-overline">Обзор маршрута</div><div class="route-city"><span class="dot"></span>${esc(p[0]?.name||'Точка отправления')}</div><div class="route-line"></div><div class="route-city end"><span class="dot"></span>${esc(p.at(-1)?.name||'Точка прибытия')}</div><div class="summary-divider"></div><div class="summary-metric"><span>Расстояние по геометрии</span><strong>${distance()?num(distance()/1000,1)+' км':'—'}</strong></div><div class="summary-metric"><span>Движение</span><strong>${state.version?duration(moving()):'—'}</strong></div><div class="summary-metric"><span>Остановки</span><strong>${state.version?duration(stopped()):'—'}</strong></div><div class="summary-metric"><span>Контрольные точки</span><strong>${p.length}</strong></div><div class="summary-metric"><span>Сообщений в треке</span><strong>${num(track.length)}</strong></div><div class="summary-divider"></div><span class="summary-help">${state.version?'Версия '+esc(state.version.number||state.versions.findIndex(v=>v.id===state.version.id)+1)+' · '+(isStale()?'историческая':'для текущей редакции'):'Постройте маршрут и выполните первый расчёт.'}</span><p class="summary-note">${t.demo?'Собственная тестовая геометрия.':'Маршрут без исторических пробок. Дорожные лимиты скорости могут быть неизвестны.'}</p></aside></div><section class="panel points-panel"><div class="panel-title"><div><h2>Контрольные точки <span class="pill" style="margin-left:7px">${p.length}</span></h2><p>Известные координаты и время · порядок посещения сохраняется</p></div><button class="small" data-action="import">${ico('upload')}Импорт / вставка</button></div><div class="table-scroll"><table class="point-table"><thead><tr><th style="width:40px">№</th><th>Место / название</th><th>Широта</th><th>Долгота</th><th>Дата и время</th><th>Событие</th><th>Пояс IANA</th><th>Источник</th><th>Радиус, м</th><th></th></tr></thead><tbody>${p.map((pt,i)=>`<tr data-point-row="${esc(pt.id)}" class="${pt.lat===''||pt.lon===''||!pt.localTime?'row-error':''}"><td><button class="point-num" data-focus-point="${i}" aria-label="Показать точку ${i+1}">${i+1}</button></td><td><input class="point-name-input" data-point="${i}" data-field="name" aria-label="Название точки ${i+1}" value="${esc(pt.name)}"></td><td><input class="coord" data-point="${i}" data-field="lat" inputmode="decimal" aria-label="Широта точки ${i+1}" value="${esc(pt.lat)}"></td><td><input class="coord" data-point="${i}" data-field="lon" inputmode="decimal" aria-label="Долгота точки ${i+1}" value="${esc(pt.lon)}"></td><td><input type="datetime-local" step="1" data-point="${i}" data-field="localTime" aria-label="Дата и время точки ${i+1}" value="${esc(pt.localTime?.slice(0,19))}"></td><td><select data-point="${i}" data-field="event" aria-label="Событие точки ${i+1}">${Object.entries(events).map(([id,l])=>`<option value="${id}" ${pt.event===id?'selected':''}>${l}</option>`).join('')}</select></td><td><input class="timezone-input" data-point="${i}" data-field="timezone" aria-label="Часовой пояс точки ${i+1}" value="${esc(pt.timezone||t.timezone)}"></td><td><select data-point="${i}" data-field="source" aria-label="Источник точки ${i+1}">${Object.entries(sources).filter(([k])=>['user','gps','document','driver'].includes(k)).map(([k,l])=>`<option value="${k}" ${pt.source===k?'selected':''}>${l}</option>`).join('')}</select></td><td><input style="width:55px" type="number" min="0" data-point="${i}" data-field="radiusM" aria-label="Радиус точки ${i+1}" value="${esc(pt.radiusM??100)}"></td><td><div class="point-actions"><button data-point-up="${i}" aria-label="Переместить вверх" ${i?'':'disabled'}>↑</button><button data-point-down="${i}" aria-label="Переместить вниз" ${i===p.length-1?'disabled':''}>↓</button><button data-point-detail="${i}" aria-label="Точность и комментарий">⋯</button><button data-point-delete="${i}" aria-label="Удалить точку">×</button></div></td></tr>`).join('')||'<tr><td colspan="10" style="text-align:center;padding:30px;color:#8b9d91">Добавьте первую контрольную точку или импортируйте таблицу.</td></tr>'}</tbody></table></div><div class="point-footer"><button class="text-button" data-action="add-point">${ico('plus')}Добавить точку</button><span>Фактические значения сохраняются · автосохранение после ввода</span></div></section>${track.length?`<section class="panel"><div class="panel-title"><div><h2>Сообщения трека</h2><p>Первые 40 строк из ${num(track.length)} · полные данные доступны в Excel</p></div>${badge('Расчётный результат','ready')}</div><div class="table-scroll"><table class="track-preview"><thead><tr><th>№</th><th>UTC</th><th>Широта</th><th>Долгота</th><th>км/ч</th><th>Пробег, км</th><th>Происхождение</th></tr></thead><tbody>${track.slice(0,40).map((r,i)=>`<tr><td>${r.seq??i+1}</td><td>${esc(localDate(r.timestampUtc))}</td><td>${num(r.lat,6)}</td><td>${num(r.lon,6)}</td><td>${num(r.speedKph,1)}</td><td>${num(r.distanceM/1000,3)}</td><td>${esc(sources[r.source]||r.source)}</td></tr>`).join('')}</tbody></table></div></section>`:''}`}
function displayTime(row){if(!row)return'—';if(state.displayZone==='local')return localDate(row.localTime);try{return new Intl.DateTimeFormat('ru-RU',{timeZone:state.displayZone,day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(row.timestampUtc))}catch{return localDate(row.timestampUtc)}}
function profileFields(p,prefix='profile'){return`<div class="form-grid">${[['weight','Фактическая масса, т',.1],['maxWeight','Разрешённая максимальная масса, т',.1],['axleWeight','Нагрузка на ось, т',.1],['height','Высота, м',.01],['width','Ширина, м',.01],['length','Длина, м',.1]].map(([k,l,step])=>`<div class="field"><label>${l}</label><input type="number" step="${step}" min="0" data-${prefix}="${k}" value="${esc(p[k])}"></div>`).join('')}<div class="field"><label>Прицеп</label><select data-${prefix}="hasTrailer"><option value="true" ${p.hasTrailer?'selected':''}>Есть прицеп</option><option value="false" ${!p.hasTrailer?'selected':''}>Без прицепа</option></select></div><div class="field"><label>Число водителей</label><select data-${prefix}="drivers"><option value="1" ${p.drivers===1?'selected':''}>1 водитель</option><option value="2" ${p.drivers===2?'selected':''}>2 водителя</option></select></div></div><div class="form-section"><h3>Допущения модели движения и отдыха</h3><div class="form-grid">${[['maxSpeedKph','Предел скорости модели, км/ч',1],['cruiseSpeedKph','Предпочтительная скорость, км/ч',1],['accelerationMps2','Ускорение / торможение, м/с²',.05],['continuousDriveHours','Непрерывное движение, ч',.25],['breakMinutes','Предпочтительная пауза, мин',5],['nightRestHours','Предпочтительный ночной отдых, ч',.5]].map(([k,l,step])=>`<div class="field"><label>${l}</label><input type="number" min="0.01" step="${step}" data-${prefix}="${k}" value="${esc(p[k])}"></div>`).join('')}<div class="field"><label>Шаг сообщений в движении</label><select data-${prefix}="stepSeconds">${[1,5,10,30,60].map(s=>`<option value="${s}" ${Number(p.stepSeconds)===s?'selected':''}>${s} секунд</option>`).join('')}</select></div><div class="field"><label>Шаг сообщений на остановке</label><select data-${prefix}="stopStepSeconds">${[1,5,10,30,60].map(s=>`<option value="${s}" ${Number(p.stopStepSeconds)===s?'selected':''}>${s} секунд</option>`).join('')}</select></div></div></div>`}
function parametersTab(){const t=state.trip;return`<div class="alert">${ico('info')}Маршрутизация: стандартный автомобильный режим (driving). Значения стартового профиля — редактируемые модельные допущения. Юридическое соответствие режиму труда и отдыха отдельно не проверяется.</div><section class="panel"><div class="panel-title"><h2>Профиль фуры и движения</h2><div style="display:flex;gap:7px"><button class="small" data-action="choose-profile">Выбрать профиль</button><button class="small" data-action="save-profile">${ico('save')}Сохранить профиль</button></div></div><div class="panel-body">${profileFields(t.profile||state.config.defaultProfile||{})}</div></section><section class="panel"><div class="panel-title"><h2>Время и исходные сведения</h2></div><div class="panel-body"><div class="form-grid two"><div class="field"><label>Режим исходного времени</label><select data-trip="timeMode"><option value="single" ${t.timeMode==='single'?'selected':''}>Единый пояс всех отметок</option><option value="local" ${t.timeMode==='local'?'selected':''}>Местное время каждой точки</option></select><small>Меняет смысл введённых часов. Проверьте все отметки перед перерасчётом.</small></div><div class="field"><label>Единый пояс IANA</label><input data-trip="timezone" value="${esc(t.timezone||'Europe/Moscow')}"></div><div class="field wide"><label>Примечания к рейсу</label><textarea data-trip="note" class="notes-field" placeholder="Источник сведений и важные обстоятельства">${esc(t.note)}</textarea></div></div><div class="form-section"><h3>Что известно о времени и ограничениях</h3><ul class="list-text"><li>Все расчёты выполняются в UTC. Пояс компьютера не используется.</li><li>Опорная точка не считается остановкой, если событие этого не задаёт.</li><li>Дорожные ограничения скорости неизвестны, если не предоставлены источником.</li><li>Выбран стандартный автомобильный режим (driving). Грузовые габариты и ограничения при построении пути не учитываются.</li></ul></div></div></section>`}
function stopStart(s){return s.startUtc||s.startTime||s.start}function stopEnd(s){return s.endUtc||s.endTime||s.end||new Date(+new Date(stopStart(s))+Number(s.durationSeconds||s.durationS||0)*1000).toISOString()}
function stopsTab(){const stops=state.version?.result?.stops||[];return`<div class="alert">${ico('moon')}Остановки неизвестны. Предложения ниже — расчётные предположения. «Закрепить» сохраняет решение для следующего расчёта, но не делает его подтверждённым событием.</div><section class="panel"><div class="panel-title"><div><h2>Предложенные остановки <span class="pill">${stops.length}</span></h2><p>Редактирование создаёт новую редакцию. Для проверки изменений выполните повторный расчёт.</p></div></div>${stops.length?`<div class="table-scroll"><table><thead><tr><th>Тип / место</th><th>Начало UTC</th><th>Окончание UTC</th><th>Длительность</th><th>Причина предложения</th><th></th></tr></thead><tbody>${stops.map((s,i)=>{const over=(state.trip.stopOverrides||[]).find(o=>o.id===s.id),deleted=over?.deleted;return`<tr class="stop-row" style="${deleted?'opacity:.45':''}"><td><div class="stop-type">${ico(s.type?.includes('night')?'moon':'pin')}${esc(s.type?.includes('night')?'Предполагаемый ночной отдых':s.type==='confirmed'?'Подтверждённая остановка':'Предполагаемая остановка')}</div><span class="source-label">${esc(s.place||s.placeName||s.locationName||'Место остановки не установлено')}</span><span class="source-label">${num(s.lat,5)}, ${num(s.lon,5)}</span></td><td>${esc(localDate(over?.startUtc||stopStart(s)))}</td><td>${esc(localDate(stopEnd(s)))}</td><td>${duration(over?.durationSeconds??s.durationSeconds??s.durationS??(+new Date(stopEnd(s))-+new Date(stopStart(s)))/1000)}</td><td class="secondary" style="max-width:230px">${esc(s.reason||'Распределение временного запаса между опорными точками')}</td><td><div style="display:flex;gap:6px"><button class="small" data-stop-edit="${i}">Изменить</button><button class="small" data-stop-pin="${i}">${over?.locked?'Закреплено':'Закрепить'}</button><button class="small danger" data-stop-delete="${i}">${deleted?'Вернуть':'Удалить'}</button></div></td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty"><div class="empty-symbol">${ico('moon')}</div><h2>Отдых появится после расчёта</h2><p>Система учитывает доступное время, профиль движения и непрерывное накопленное вождение.</p><button class="primary" data-action="calculate">Рассчитать движение и отдых</button></div>`}</section>`}
function checksTab(){const checks=resultChecks();return`<section class="panel"><div class="panel-title"><div><h2>Проверки и допущения</h2><p>${state.version?'Проверки выбранной версии расчёта':'Проверки появятся после построения и расчёта'}</p></div>${state.version?badge(isStale()?'Историческая версия':'Для текущей редакции',isStale()?'warn':'ready'):''}</div>${checks.length?checks.map((c,i)=>`<div class="check-card ${c.severity==='error'||c.severity==='conflict'?'error':c.severity==='success'?'success':''}">${ico(c.severity==='success'?'check':c.severity==='error'?'alert':'info')}<div><strong>${esc(c.message||c.title||c.code)}</strong>${c.details?`<p>${esc(typeof c.details==='string'?c.details:JSON.stringify(c.details))}</p>`:''}${c.legIndex!=null?`<p>Участок ${Number(c.legIndex)+1} → ${Number(c.legIndex)+2}</p>`:''}</div>${c.legIndex!=null?`<button class="small" data-check-leg="${c.legIndex}">На карту</button>`:''}</div>`).join(''):`<div class="check-card">${ico('info')}<div>Нет сохранённых сообщений проверки. Выполните расчёт.</div></div>`}</section><section class="panel"><div class="panel-title"><h2>Принято в модели</h2></div><div class="panel-body"><ul class="list-text">${(state.version?.result?.assumptions||['Профиль фуры и режима движения задаётся пользователем.','Места предполагаемых остановок требуют отдельного подтверждения.','Исторические пробки не восстанавливаются.']).map(a=>`<li>${esc(typeof a==='string'?a:a.message||JSON.stringify(a))}</li>`).join('')}</ul><div class="mini-label" style="margin-top:17px">Алгоритм: ${esc(state.version?.result?.algorithmVersion||state.config.algorithmVersion||'—')} · фактическое GPS-покрытие по редким отметкам не определено.</div></div></section>`}
function versionsTab(){return`<section class="panel"><div class="panel-title"><div><h2>Версии расчёта</h2><p>Каждая версия хранит собственный снимок исходных данных. Неудачный запуск не заменяет успешный результат.</p></div><button class="small" data-action="compare" ${state.versions.length<2?'disabled':''}>Сравнить версии</button></div><div class="panel-body">${state.versions.length?state.versions.map((v,i)=>`<div class="version-card ${state.version?.id===v.id?'selected':''}"><div class="version-number">v${v.number||state.versions.length-i}</div><div class="version-main"><strong>Расчёт от ${date(v.createdAt)}</strong><p>Редакция ${v.revision??v.sourceRevision??'—'} · ${esc(v.status==='completed'?'Завершён':v.status==='conflict'?'Конфликт':v.status||'Результат')}${isStale(v)?' · исходные данные изменились':''}</p></div><div class="version-metrics"><span>${num((v.summary?.distanceM||v.result?.summary?.distanceM||0)/1000,1)} км</span><span>${v.status==='completed'?badge('Сохранена','ready'):badge(v.status||'Версия','warn')}</span></div><button class="small" data-version="${esc(v.id)}">${state.version?.id===v.id?'Выбрана':'Открыть'}</button></div>`).join(''):'<div class="empty"><h2>Пока нет версий</h2><p>Первый расчёт создаст неизменяемый результат и снимок исходных данных.</p></div>'}</div></section>`}
function exportsTab(){return`<section class="panel"><div class="panel-title"><div><h2>Выгрузки Excel</h2><p>Сохранённые файлы привязаны к точной версии. Создание файла не означает передачу клиенту.</p></div><button class="primary small" data-action="export" ${!state.version?.result?.track?.length?'disabled':''}>${ico('download')}Новая выгрузка</button></div>${state.exports.length?`<div class="table-scroll"><table><thead><tr><th>Файл</th><th>Создан</th><th>Версия</th><th>Профиль / пояс</th><th></th></tr></thead><tbody>${state.exports.map(e=>`<tr><td><div class="label-row">${ico('file')}<span>${esc(e.filename||'Восстановленный маршрут.xlsx')}</span></div></td><td>${date(e.createdAt)}</td><td>${esc(e.versionId?.slice(0,8)||'—')}</td><td>${esc(e.profile?.name||'Универсальный')}<span class="source-label">${esc(e.profile?.timezone||'Местное время')}</span></td><td><a href="${esc(e.url||'/api/exports/'+encodeURIComponent(e.id)+'/download')}" download><button class="small">${ico('download')}Скачать</button></a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><div class="empty-symbol">'+ico('file')+'</div><h2>Отчёты ещё не создавались</h2><p>Универсальный XLSX содержит сведения о рейсе, исходные точки, весь трек, стоянки и проверки.</p></div>'}</section><div class="hint-card">${ico('info')}<p><strong>XLSX — отчёт о реконструкции.</strong><br>Совместимость с неизвестным форматом клиента и импорт в Wialon не подтверждены. Экспортёр для конкретного протокола подключается отдельно.</p></div>`}
function updateSaveState(){const el=$('#save-state');if(el){el.innerHTML=saveLabel();el.className='save-state'+(state.saveStatus?.startsWith('Ошибка')?' error':state.dirty?' dirty':'')}const notice=$('#stale-notice');if(notice)notice.innerHTML=staleNotice()}
function markDirty(){state.edit++;state.dirty=true;state.saveStatus='Есть несохранённые изменения';updateSaveState();clearTimeout(state.saveTimer);state.saveTimer=setTimeout(()=>saveTrip(),800)}
async function saveTrip(){clearTimeout(state.saveTimer);if(!state.trip||!state.dirty)return true;if(state.saving){state.saveAgain=true;return state.savePromise}const id=state.trip.id,edit=state.edit,payload=structuredClone(state.trip);state.saving=true;state.saveStatus='Сохраняется…';updateSaveState();state.savePromise=(async()=>{try{const saved=await api('/api/trips/'+encodeURIComponent(id),{method:'PUT',body:payload});if(state.trip?.id!==id)return true;state.trip.revision=saved.revision;state.trip.updatedAt=saved.updatedAt;if(state.edit===edit){state.trip=saved;state.dirty=false;state.saveStatus='Сохранено в '+new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Europe/Moscow'}).format(new Date());}else{state.dirty=true;state.saveStatus='Есть новые изменения';state.saveAgain=true}return true}catch(e){if(state.trip?.id===id){state.saveStatus=e.status===409?'Ошибка: конфликт редакций':'Ошибка сохранения: '+e.message;toast(e.status===409?'В другой вкладке сохранена более новая редакция. Ваш ввод остаётся здесь. Скачайте черновик или откройте актуальные данные.':e.message,true);if(e.status===409)conflictDialog()}return false}finally{state.saving=false;updateSaveState();if(state.saveAgain){state.saveAgain=false;state.saveTimer=setTimeout(()=>saveTrip(),100)}}})();return state.savePromise}
async function flushSave(){clearTimeout(state.saveTimer);if(state.saving)await state.savePromise;if(state.dirty)return saveTrip();return true}
