async function previewImport(){try{const input=state.importData||{text:$('#import-text').value};if(!input.text&&!input.base64){toast('Вставьте таблицу или выберите файл',true);return}state.importData=input;const r=await api('/api/import',{method:'POST',body:input});state.importPreview=r;const headers=r.headers||[];const choices={name:'Название',lat:'Широта',lon:'Долгота',localTime:'Дата и время',date:'Дата отдельно',time:'Время отдельно',timezone:'Пояс IANA',event:'Событие',source:'Источник'};const aliases={name:['name','название','место','точка'],lat:['lat','latitude','широта'],lon:['lon','lng','longitude','долгота'],localTime:['localtime','datetime','время','дата и время','timestamp','time'],date:['дата','date'],time:['часы','time'],timezone:['timezone','пояс','iana'],event:['event','событие'],source:['source','источник']};$('#import-preview').innerHTML=`<div class="import-options"><h3>Сопоставление столбцов</h3><div class="form-grid two">${Object.entries(choices).map(([key,label])=>{const guess=headers.find(h=>aliases[key].includes(String(h).toLowerCase().trim()));return`<div class="field"><label>${label}</label><select data-import-mapping="${key}"><option value="">Не выбран</option>${headers.map(h=>`<option value="${esc(h)}" ${guess===h?'selected':''}>${esc(h)}</option>`).join('')}</select></div>`}).join('')}</div><div class="import-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${(r.rows||[]).slice(0,5).map(row=>`<tr>${headers.map((h,i)=>`<td>${esc(Array.isArray(row)?row[i]:row[h])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="mini-label">${r.rows?.length||r.points?.length||0} строк. Существующие отметки не перезаписываются.</p></div>`;$('[data-action="apply-import"]').disabled=false;}catch(e){toast(e.message,true)}}
async function applyImport(){const mapping=Object.fromEntries($$('[data-import-mapping]').filter(e=>e.value).map(e=>[e.dataset.importMapping,e.value]));if(!mapping.lat||!mapping.lon||(!mapping.localTime&&!(mapping.date&&mapping.time))){toast('Сопоставьте широту, долготу и дату / время.',true);return}try{const r=await api('/api/import',{method:'POST',body:{...state.importData,mapping,timezone:state.trip.timezone}});if(r.errors?.length){$('#import-preview').insertAdjacentHTML('afterbegin',`<div class="alert error">${r.errors.map(e=>esc(typeof e==='string'?e:e.message||JSON.stringify(e))).join('<br>')}</div>`);return}if(!r.points?.length){toast('Нет контрольных точек для добавления',true);return}state.trip.points||=[];state.trip.points.push(...r.points.map(p=>({id:crypto.randomUUID(),source:'user',timezone:state.trip.timezone,event:'pass',radiusM:100,...p,timezone:p.timezone||state.trip.timezone})));markDirty();$('#modal').close();card();toast(`Добавлено точек: ${r.points.length}`)}catch(e){toast(e.message,true)}}
async function exportDialog(){if(!state.version?.result?.track?.length)return;let profile=state.settings.exportProfile||{};modal('Выгрузить расчётный маршрут',`<p class="modal-note">Файл относится к выбранной версии ${esc(state.version.id.slice(0,8))}. ${isStale()?'Выбрана историческая версия; она будет явно обозначена в отчёте.':''} Все листы сохраняют сведения о расчётном происхождении.</p><div class="form-grid two"><div class="field"><label>Название экспортного профиля</label><input id="export-name" value="${esc(profile.name||'Универсальный отчёт')}"></div><div class="field"><label>Пояс отображения</label><input id="export-zone" value="${esc(profile.timezone||state.trip.timezone||'Europe/Moscow')}"></div><div class="field"><label>Формат даты</label><select id="export-date"><option value="yyyy-MM-dd HH:mm:ss">ГГГГ-ММ-ДД ЧЧ:мм:сс</option><option value="dd.MM.yyyy HH:mm:ss" ${profile.dateFormat==='dd.MM.yyyy HH:mm:ss'?'selected':''}>ДД.ММ.ГГГГ ЧЧ:мм:сс</option></select></div><div class="field"><label>Единицы расстояния</label><select id="export-distance"><option value="km">Километры</option><option value="m" ${profile.distanceUnit==='m'?'selected':''}>Метры</option></select></div></div><div class="form-section"><h3>Дополнительные столбцы трека</h3><div class="export-options">${[['course','Курс'],['distanceM','Пробег'],['state','Состояние'],['events','События'],['pointId','Связь с опорой']].map(([key,label])=>`<label><input type="checkbox" data-export-column="${key}" ${!profile.columns||profile.columns.includes(key)?'checked':''}>${label}</label>`).join('')}</div><div class="mini-label">Время, координаты и происхождение данных сохраняются независимо от оформления.</div></div>`,`<button data-close>Отмена</button><button class="primary" data-action="generate-export">${ico('download')}Создать Excel</button>`)}
async function generateExport(){const version=state.version;const profile={name:$('#export-name').value,timezone:$('#export-zone').value,dateFormat:$('#export-date').value,distanceUnit:$('#export-distance').value,columns:['timestampUtc','localTime','displayTime','displayTimezone','timezone','utcOffsetMinutes','lat','lon','speedKph','source',...$$('[data-export-column]').filter(e=>e.checked).map(e=>e.dataset.exportColumn)]};const button=$('[data-action="generate-export"]');button.disabled=true;button.innerHTML='<span class="spinner"></span>Создаём файл…';try{const r=await api('/api/versions/'+encodeURIComponent(version.id)+'/exports',{method:'POST',body:{profile}});state.settings.exportProfile=profile;await api('/api/settings',{method:'PUT',body:{exportProfile:profile}});$('#modal').close();const a=document.createElement('a');a.href=r.url||'/api/exports/'+r.id+'/download';a.download=r.filename||'Рейс.xlsx';a.click();state.exports=(await api('/api/trips/'+state.trip.id+'/exports')).items||[];toast('Excel сформирован и сохранён. Повторное скачивание доступно в «Выгрузках».');if(state.tab==='exports')card()}catch(e){button.disabled=false;button.innerHTML=ico('download')+'Создать Excel';toast(e.message,true)}}
async function compareVersions(){if(state.versions.length<2)return;modal('Сравнение версий',`<div class="form-grid two"><div class="field"><label>Первая версия</label><select id="compare-a">${state.versions.map((v,i)=>`<option value="${esc(v.id)}">v${v.number||state.versions.length-i} · ${date(v.createdAt)}</option>`).join('')}</select></div><div class="field"><label>Вторая версия</label><select id="compare-b">${state.versions.map((v,i)=>`<option value="${esc(v.id)}" ${i===1?'selected':''}>v${v.number||state.versions.length-i} · ${date(v.createdAt)}</option>`).join('')}</select></div></div><div id="compare-content"></div>`,`<button data-close>Закрыть</button><button class="primary" data-action="load-compare">Сравнить</button>`);await loadCompare()}
async function loadCompare(){try{const[a,b]=await Promise.all([api('/api/versions/'+$('#compare-a').value),api('/api/versions/'+$('#compare-b').value)]);const assumptions=v=>(v.result?.assumptions||[]).map(a=>typeof a==='string'?a:a.message||JSON.stringify(a)).join('; ');const points=v=>v.snapshot?.points?.map(p=>p.name||`${p.lat}, ${p.lon}`).join(' → ')||'—';$('#compare-content').innerHTML=`<div class="table-scroll" style="margin-top:20px"><table><thead><tr><th>Показатель</th><th>Первая версия</th><th>Вторая версия</th></tr></thead><tbody>${[['Расстояние',num(distance(a)/1000,1)+' км',num(distance(b)/1000,1)+' км'],['Движение',duration(moving(a)),duration(moving(b))],['Остановки',duration(stopped(a)),duration(stopped(b))],['Опорные условия',a.result?.checks?.filter(c=>c.severity==='error').length?'Есть конфликты':'Нет конфликтов проверки',b.result?.checks?.filter(c=>c.severity==='error').length?'Есть конфликты':'Нет конфликтов проверки'],['Путь',points(a),points(b)],['Допущения',assumptions(a),assumptions(b)]].map(row=>`<tr>${row.map((v,i)=>`<${i?'td':'th'} style="white-space:normal;min-width:130px;line-height:1.7">${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</tbody></table></div>`}catch(e){toast(e.message,true)}}
async function profilesPage(){try{const r=await api('/api/profiles');state.profiles=r.items||[];shell(`<div class="page-heading"><div><div class="eyebrow">Сохранённые допущения</div><h1>Профили фур</h1><p class="subtitle">Параметры автомобиля, движения и отдыха для следующих рейсов.</p></div><button class="primary" data-action="new-profile">${ico('plus')}Новый профиль</button></div><div class="alert">${ico('info')}Стартовые значения — модельные допущения. Они не подтверждают характеристики реальной фуры и не являются правовой проверкой.</div><section class="panel"><div class="panel-title"><h2>Мои профили</h2></div><div class="panel-body">${state.profiles.length?state.profiles.map((p,i)=>`<div class="version-card"><span class="version-number">${ico('truck')}</span><div class="version-main"><strong>${esc(p.name||'Профиль фуры')}</strong><p>${num(p.weight??p.profile?.weight)} т · ${num(p.height??p.profile?.height,2)} м · ${num(p.length??p.profile?.length,1)} м · предел ${p.maxSpeedKph??p.profile?.maxSpeedKph??80} км/ч</p></div><button class="small" data-profile-edit="${i}">Изменить</button></div>`).join(''):'<div class="empty"><h2>Сохраните свой первый профиль</h2><p>Редактируемый стартовый профиль уже доступен в параметрах нового рейса.</p><button class="primary" data-action="new-profile">Создать профиль</button></div>'}</div></section>`)}catch(e){toast(e.message,true)}}
function editProfile(i){const p=i==null?{...state.config.defaultProfile,name:'Моя фура',id:crypto.randomUUID()}:structuredClone(state.profiles[i]);state.editingProfile=p;modal('Профиль фуры',`<div class="field" style="margin-bottom:22px"><label>Название профиля</label><input id="profile-name" value="${esc(p.name)}"></div>${profileFields(p.profile||p,'editprofile')}`,`<button data-close>Отмена</button><button class="primary" data-action="store-profile">Сохранить профиль</button>`)}
async function storeProfile(){const p=state.editingProfile,payload={...(p.profile||p),name:$('#profile-name').value,id:p.id||crypto.randomUUID()};$$('[data-editprofile]').forEach(el=>payload[el.dataset.editprofile]=el.dataset.editprofile==='hasTrailer'?el.value==='true':Number(el.value));const items=state.profiles.filter(x=>x.id!==payload.id).concat(payload);await api('/api/profiles',{method:'PUT',body:{items}});state.profiles=items;$('#modal').close();toast('Профиль сохранён');if(state.page==='profiles')await profilesPage()}
async function chooseProfile(){state.profiles=(await api('/api/profiles')).items||[];modal('Выбрать профиль',`<p class="modal-note">Профиль меняет параметры черновика. Старые версии расчёта сохраняются.</p><div class="field"><label>Сохранённые профили</label><select id="choose-profile"><option value="default">Стартовый профиль · модельные значения</option>${state.profiles.map((p,i)=>`<option value="${i}">${esc(p.name||'Профиль '+(i+1))}</option>`).join('')}</select></div>`,`<button data-close>Отмена</button><button class="primary" data-action="apply-profile">Применить</button>`)}
async function settingsPage(){state.settings=await api('/api/settings');shell(`<div class="page-heading"><div><div class="eyebrow">Рабочее пространство</div><h1>Настройки</h1><p class="subtitle">Интеграции, сохранность данных и резервные копии.</p></div></div><div class="settings-layout"><section class="panel"><div class="panel-title"><h2>Яндекс: карта и грузовые маршруты</h2></div><div class="panel-body"><div class="integration-row"><span class="trip-icon">${ico('route')}</span><div><strong>HTTP Router API · mode=truck</strong><p>${state.config.routingConfigured?'Серверный ключ настроен. Доступ к продукту проверяется запросом.':'Серверный ключ не настроен. Укажите YANDEX_ROUTER_KEY в окружении.'}</p></div>${badge(state.config.routingConfigured?'Ключ настроен':'Не подключено',state.config.routingConfigured?'ready':'warn')}</div><div class="integration-row"><span class="trip-icon">${ico('pin')}</span><div><strong>Яндекс Карты JavaScript API v3</strong><p>${state.config.mapKey?'Браузерный ключ настроен.':'Отдельный браузерный ключ YANDEX_MAP_KEY пока не настроен.'}</p></div>${badge(state.config.mapKey?'Подключено':'Схема без подложки',state.config.mapKey?'ready':'warn')}</div><div class="actions-row"><button data-action="check-integration">${ico('refresh')}Проверить подключение</button></div><div id="integration-result"></div><div class="form-section"><label class="checkbox"><input id="license-confirmed" type="checkbox" ${state.settings.licenseConfirmed?'checked':''}>Я проверил договор и право сохранять дорожную геометрию и экспортировать производные данные. Ключ сам по себе не подтверждает эти права.</label><div class="mini-label" style="margin-top:12px">Для прошлых рейсов используется traffic=disabled: исторические пробки не воспроизводятся, критерий выбора маршрута — кратчайшее расстояние.</div></div></div></section><section class="panel"><div class="panel-title"><h2>Резервные копии и восстановление</h2></div><div class="panel-body"><p class="modal-note">Копия содержит рейсы, профили, неизменяемые версии и сохранённые выгрузки. API-ключи не включаются. Перед заменой данных выполняется проверка копии.</p><div class="form-grid two"><div class="field"><label>Автоматическая копия каждые, часов</label><input type="number" id="backup-interval" min="1" max="8760" value="${state.settings.backupIntervalHours??24}"><small>В локальном режиме — при работающем приложении.</small></div><div class="field"><label>Хранить последних копий</label><input type="number" id="backup-retention" min="1" max="100" value="${state.settings.backupRetention??7}"></div></div><div class="actions-row"><a href="/api/backup" download><button>${ico('download')}Создать резервную копию</button></a><button data-action="restore-dialog">${ico('upload')}Восстановить из копии</button></div></div></section><div class="actions-row"><button class="primary" data-action="save-settings">${ico('save')}Сохранить настройки</button></div><div class="bottom-note">${ico('shield')}Хранилище: ${esc(state.config.storage||'постоянная база приложения')}. Источники и расчётные версии сохраняются раздельно.</div></div>`)}
async function saveSettings(){state.settings={...state.settings,licenseConfirmed:$('#license-confirmed').checked,backupIntervalHours:Number($('#backup-interval').value),backupRetention:Number($('#backup-retention').value)};state.settings=await api('/api/settings',{method:'PUT',body:state.settings});state.config.licenseConfirmed=state.settings.licenseConfirmed;toast('Настройки сохранены')}
async function checkIntegration(){const el=$('#integration-result');el.innerHTML='<p class="mini-label"><span class="spinner"></span> Проверяем права API…</p>';try{const r=await api('/api/integration/check',{method:'POST',body:{}});el.innerHTML=Object.entries(r).filter(([,v])=>v&&typeof v==='object').map(([k,v])=>`<div class="alert ${v.ok?'success':'error'}" style="margin-top:14px">${ico(v.ok?'check':'alert')}<div><strong>${esc(k==='routing'?'Маршрутизация':k==='map'?'Карта':k)}</strong><br>${esc(v.message||JSON.stringify(v))}</div></div>`).join('')}catch(e){el.innerHTML=`<div class="alert error" style="margin-top:14px">${esc(e.message)}</div>`}}
function restoreDialog(){modal('Восстановить резервную копию',`<p class="modal-note">Сначала проверим структуру и совместимость. Замена текущего рабочего пространства потребует отдельного подтверждения после проверки. Предыдущее состояние сохраняется.</p><div class="field"><label>Файл резервной копии JSON</label><input type="file" id="restore-file" accept=".json"></div><div id="restore-summary"></div>`,`<button data-close>Отмена</button><button class="primary" data-action="restore-confirm" disabled>Проверка не выполнена</button>`);$('#restore-file').addEventListener('change',restoreFile)}
async function restoreFile(e){const file=e.target.files[0];if(!file)return;try{if(file.size>12*1024*1024)throw new Error('Копия превышает 12 МБ');const backup=JSON.parse(await file.text());const r=await api('/api/restore/validate',{method:'POST',body:{backup}});state.restoreToken=r.token;$('#restore-summary').innerHTML=`<div class="alert success" style="margin-top:18px">${ico('check')}<div><strong>Копия проверена</strong><br>${esc(typeof r.summary==='string'?r.summary:JSON.stringify(r.summary))}</div></div><p class="modal-note">Нажмите «Заменить рабочее пространство», чтобы восстановить данные из проверенной копии.</p>`;const b=$('[data-action="restore-confirm"]');b.disabled=false;b.textContent='Заменить рабочее пространство'}catch(e){toast('Копия не прошла проверку: '+e.message,true)}}
async function restoreConfirm(){await api('/api/restore',{method:'POST',body:{token:state.restoreToken}});$('#modal').close();state.trip=null;state.dirty=false;state.page='trips';state.offset=0;await loadTrips();toast('Рабочее пространство восстановлено из копии')}
async function navigate(page){if(!await flushSave())return;stopPlayback();state.page=page;state.request++;if(page!=='card')history.replaceState(null,'','#'+page);if(page==='trips'||page==='archive'){state.offset=0;await loadTrips()}else if(page==='settings')await settingsPage();else if(page==='profiles')await profilesPage()}
async function action(name){switch(name){case'new':return newTripDialog();case'create-trip':{const form=$('#new-trip-form');if(!form.reportValidity())return;const payload=Object.fromEntries(new FormData(form));const trip=await api('/api/trips',{method:'POST',body:payload});$('#modal').close();return openTrip(trip.id)}case'demo':{if(!await flushSave())return;const t=await api('/api/demo',{method:'POST',body:{}});await openTrip(t.id);toast('Создан собственный демонстрационный рейс. Нажмите «Рассчитать».');return}case'refresh':return loadTrips();case'next':state.offset+=30;return loadTrips();case'previous':state.offset=Math.max(0,state.offset-30);return loadTrips();case'save':return saveTrip();case'route':return buildRoute();case'calculate':return calculate();case'variant':{if(!await flushSave())return;const t=await api('/api/trips/'+state.trip.id+'/variant',{method:'POST',body:{versionId:state.version.id}});await openTrip(t.id);toast('Создан редактируемый вариант текущего сценария');return}case'export':return exportDialog();case'generate-export':return generateExport();case'add-point':return addPoint();case'map-add':state.addMapPoint=!state.addMapPoint;toast(state.addMapPoint?'Нажмите на карту или схему. Для новой точки нужно будет указать время.':'Добавление на карте отключено');return;case'import':return importDialog();case'preview-import':return previewImport();case'apply-import':return applyImport();case'play':return play();case'compare':return compareVersions();case'load-compare':return loadCompare();case'download-draft':return downloadObject(state.trip,'Черновик-рейса-'+state.trip.id+'.json');case'reload-trip':{const id=state.trip.id;state.dirty=false;state.saving=false;$('#modal').close();return openTrip(id)}case'choose-profile':return chooseProfile();case'apply-profile':{const choice=$('#choose-profile').value;const p=choice==='default'?state.config.defaultProfile:state.profiles[Number(choice)];state.trip.profile=structuredClone(p.profile||p);delete state.trip.profile.id;markDirty();$('#modal').close();card();toast('Профиль применён к черновику');return}case'save-profile':{state.profiles=(await api('/api/profiles')).items||[];state.editingProfile={...state.trip.profile,id:crypto.randomUUID(),name:state.trip.profile?.name||'Профиль рейса'};modal('Сохранить профиль',`<div class="field"><label>Название профиля</label><input id="save-profile-name" value="${esc(state.editingProfile.name)}"></div>`,`<button data-close>Отмена</button><button class="primary" data-action="store-current-profile">Сохранить</button>`);return}case'store-current-profile':{const profile={...state.editingProfile,name:$('#save-profile-name').value};await api('/api/profiles',{method:'PUT',body:{items:[...state.profiles,profile]}});$('#modal').close();toast('Профиль фуры сохранён');return}case'new-profile':return editProfile();case'store-profile':return storeProfile();case'save-settings':return saveSettings();case'check-integration':return checkIntegration();case'restore-dialog':return restoreDialog();case'restore-confirm':return restoreConfirm();case'menu-copy':{const t=await api('/api/trips/'+state.menuTrip+'/copy',{method:'POST',body:{}});$('#modal').close();return openTrip(t.id)}case'menu-archive':{const t=state.trips.find(t=>t.id===state.menuTrip);await api('/api/trips/'+state.menuTrip+'/archive',{method:'POST',body:{archived:!t?.archived}});$('#modal').close();toast(t?.archived?'Рейс восстановлен из архива':'Рейс перемещён в архив');return loadTrips()}}}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a,[data-open]');if(!target)return;try{if(target.hasAttribute('data-close')){$('#modal').close();return}if(target.dataset.nav){event.preventDefault();return await navigate(target.dataset.nav)}if(target.dataset.action){event.preventDefault();return await action(target.dataset.action)}if(target.dataset.menu){event.stopPropagation();state.menuTrip=target.dataset.menu;const t=state.trips.find(t=>t.id===state.menuTrip);modal(esc(t?.title||'Рейс'),`<p class="modal-note">Копия получает новый идентификатор и сохраняет связь с исходным рейсом. Архивный рейс можно открыть и восстановить.</p>`,`<button data-close>Закрыть</button><button data-action="menu-copy">${ico('copy')}Создать копию</button><button data-action="menu-archive">${ico('archive')}${t?.archived?'Восстановить':'В архив'}</button>`);return}if(target.dataset.open)return await openTrip(target.dataset.open);if(target.dataset.tab){stopPlayback();state.tab=target.dataset.tab;card();return}if(target.dataset.version){state.version=await api('/api/versions/'+target.dataset.version);state.playIndex=0;state.tab='points';card();toast('Выбрана сохранённая версия расчёта');return}if(target.dataset.profileEdit!==undefined)return editProfile(Number(target.dataset.profileEdit));if(target.dataset.focusPoint!==undefined)return focusPoint(Number(target.dataset.focusPoint));if(target.dataset.checkLeg!==undefined){state.tab='points';card();setTimeout(()=>focusPoint(Number(target.dataset.checkLeg)),50);return}if(target.dataset.pointDetail!==undefined)return pointDetail(Number(target.dataset.pointDetail));if(target.dataset.pointDetailSave!==undefined){const p=state.trip.points[Number(target.dataset.pointDetailSave)];p.comment=$('#point-comment').value;p.coordinatePrecisionM=Number($('#point-precision').value);p.timePrecisionSeconds=Number($('#time-precision').value);p.locked=$('#point-locked').value==='true';if($('#point-offset').value==='')delete p.utcOffsetMinutes;else p.utcOffsetMinutes=Number($('#point-offset').value);markDirty();$('#modal').close();return}if(target.dataset.pointDelete!==undefined){const i=Number(target.dataset.pointDelete);state.trip.points.splice(i,1);markDirty();card();return}if(target.dataset.pointUp!==undefined||target.dataset.pointDown!==undefined){const i=Number(target.dataset.pointUp??target.dataset.pointDown),j=target.dataset.pointUp!==undefined?i-1:i+1;[state.trip.points[i],state.trip.points[j]]=[state.trip.points[j],state.trip.points[i]];markDirty();card();return}if(target.dataset.stopEdit!==undefined)return editStop(Number(target.dataset.stopEdit));if(target.dataset.stopPin!==undefined){const i=Number(target.dataset.stopPin),s=state.version.result.stops[i],over=(state.trip.stopOverrides||[]).find(o=>o.id===s.id);return changeStop(i,{locked:!over?.locked})}if(target.dataset.stopDelete!==undefined){const i=Number(target.dataset.stopDelete),s=state.version.result.stops[i],over=(state.trip.stopOverrides||[]).find(o=>o.id===s.id);return changeStop(i,{deleted:!over?.deleted,locked:true})}if(target.dataset.stopSave!==undefined){const i=Number(target.dataset.stopSave),start=$('#stop-start').value;if(!start){toast('Укажите начало остановки',true);return}const patch={startUtc:new Date(start+'Z').toISOString(),durationSeconds:Number($('#stop-duration').value)*60,lat:Number($('#stop-lat').value),lon:Number($('#stop-lon').value),locked:$('#stop-lock').checked};$('#modal').close();changeStop(i,patch);return}}catch(e){toast(e.message,true)}});
window.addEventListener('beforeunload',e=>{if(state.dirty||state.saving){e.preventDefault();e.returnValue=''}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='new-trip-form')action('create-trip').catch(error=>toast(error.message,true))});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state.dirty)saveTrip()});
async function init(){try{state.config=await api('/api/config');state.settings=await api('/api/settings');const match=location.hash.match(/^#trip=(.+)/);if(match){await openTrip(decodeURIComponent(match[1]));return}state.page=['archive','profiles','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'trips';await navigate(state.page)}catch(e){shell(`<div class="empty"><div class="empty-symbol">${ico('alert')}</div><h2>Не удалось открыть рабочее пространство</h2><p>${esc(e.message)}</p><button class="primary" onclick="location.reload()">Повторить подключение</button></div>`)}}
init();


